<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';use InaudisVote\Core\Authorization;use InaudisVote\Core\Csrf;use InaudisVote\Services\ElectionService;use InaudisVote\Services\OrganizationService;$user=Authorization::requireRoles(['admin','organizer']);$error=null;$organizations=($user['role']==='admin')?OrganizationService::all():[];if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::validate($_POST['_csrf']??null)){$error='Solicitud inválida.';}else{try{if($user['role']==='organizer')$_POST['organization_id']=$user['organization_id'];$id=ElectionService::create($_POST,(int)$user['id']);header('Location: /election.php?id='.$id);exit;}catch(Throwable $e){$error=$e->getMessage();}}}$elections=ElectionService::allForUser($user);function sc(string $s):string{return $s==='open'?'v-status-open':($s==='closed'?'v-status-closed':'v-status-draft');}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Votaciones | QUORUM</title><link rel="stylesheet" href="/assets/quorum.css"></head><body class="vota-ui"><div class="v-shell"><aside class="v-sidebar"><div class="v-brand"><img class="v-brandmark" src="/assets/quorum-mark.svg" alt=""><span><span class="v-brand-name">QUORUM<small>by INAUDIS</small></span></span></div><nav class="v-nav"><a href="/dashboard.php">⌂ &nbsp; Inicio</a><a class="active" href="/elections.php">✓ &nbsp; Votaciones</a><?php if($user['role']==='admin'):?><a href="/organizations.php">▦ &nbsp; Organizaciones</a><a href="/users.php">♙ &nbsp; Usuarios</a><?php endif;?><a href="/audit.php">◷ &nbsp; Auditoría</a></nav><div class="v-sidebar-foot"><?=htmlspecialchars($user['name'])?><br><?=htmlspecialchars($user['role'])?></div></aside><div class="v-main"><header class="v-topbar"><a class="v-link" href="/logout.php">Salir</a></header><main class="v-content"><div class="v-headrow"><div><div class="v-kicker">Gestión electoral</div><h1 class="v-title">Votaciones</h1><div class="v-accent-line"></div><p class="v-subtitle">Crea, configura y supervisa tus procesos.</p></div></div><?php if($error):?><div class="v-alert v-alert-error"><?=htmlspecialchars($error)?></div><?php endif;?><div class="v-grid-2"><section class="v-card v-pad"><h2 style="margin-top:0">Nueva votación</h2><p class="v-muted" style="font-size:13px">Define la configuración inicial. Luego podrás cargar padrón y papeleta.</p><form method="post" class="v-stack"><?=Csrf::input()?><?php if($user['role']==='admin'):?><select name="organization_id" required class="v-field"><option value="">Organización</option><?php foreach($organizations as $o):?><option value="<?=$o['id']?>"><?=htmlspecialchars($o['name'])?></option><?php endforeach;?></select><?php endif;?><input class="v-field" name="title" required placeholder="Título de la votación"><textarea class="v-field" name="description" placeholder="Descripción"></textarea><select class="v-field" name="voting_mode"><option value="secret">Voto secreto</option><option value="public">Voto público</option></select><label class="v-label">Inicio<input class="v-field" type="datetime-local" name="starts_at"></label><label class="v-label">Término<input class="v-field" type="datetime-local" name="ends_at"></label><label class="v-check"><input type="checkbox" name="allow_weighted_vote" value="1"> Permitir voto ponderado</label><button class="v-btn v-btn-orange">Crear votación →</button></form></section><section><div class="v-section-head"><h2 style="margin:0">Procesos</h2><span class="v-muted"><?=count($elections)?> registrados</span></div><div class="v-card v-list"><?php if(!$elections):?><div class="v-row"><span class="v-muted">Aún no hay votaciones.</span></div><?php endif;?><?php foreach($elections as $e):?><a class="v-row" href="/election.php?id=<?=$e['id']?>"><div><div class="v-row-title"><?=htmlspecialchars($e['title'])?></div><div class="v-muted" style="font-size:13px"><?=htmlspecialchars($e['organization_name'])?></div></div><span class="v-status <?=sc($e['status'])?>"><?=htmlspecialchars($e['status'])?></span></a><?php endforeach;?></div></section></div></main></div></div></body></html>